public class ImmutabilityDemo {
    public static void main(String[] args) {

        String original = "hello";
        String upper = original.toUpperCase();

        // original is unchanged
        System.out.println(original); // hello
        System.out.println(upper);    // HELLO

        // They are different objects on the heap
        System.out.println(original == upper); // false — different addresses

        // Even concat creates a new object
        String s1 = "java";
        String s2 = s1.concat(" rocks");
        System.out.println(s1); // java — untouched
        System.out.println(s2); // java rocks — new object

        // Variable reassignment is NOT mutation
        String s = "start";
        s = s + "!";
        // 'start' still exists as an object; s now points to 'start!'
        // The original object was not modified — a new one was created
    }
}
