import java.util.List;

public class ConcatDemo {
    public static void main(String[] args) {
        List<String> words = List.of("Java", " is", " fast", " with", " StringBuilder");

        // BAD — creates a new String object on every iteration
        String slow = "";
        for (String word : words) {
            slow = slow + word; // allocates new object, copies all previous chars, discards old
        }
        System.out.println(slow); // Java is fast with StringBuilder

        // GOOD — one buffer, no intermediate objects
        StringBuilder sb = new StringBuilder();
        for (String word : words) {
            sb.append(word); // just writes to the internal buffer
        }
        String fast = sb.toString(); // exactly one String created at the end
        System.out.println(fast); // Java is fast with StringBuilder

        // For a single line (not in a loop), + is fine — compiler converts it:
        String oneLine = "Java" + " is" + " great"; // compiler rewrites as StringBuilder
    }
}
